<?php require_once __DIR__.'/../config/config.php';$u=require_role(['parent','student']);$ids=linked_student_ids($u);if(!$ids)json_response(['success'=>true,'students'=>[]]);$ph=implode(',',array_fill(0,count($ids),'?'));$st=db()->prepare("SELECT s.*,t.name teacher_name FROM students s JOIN users t ON t.id=s.teacher_id WHERE s.id IN ($ph) ORDER BY s.name");$st->execute($ids);json_response(['success'=>true,'students'=>$st->fetchAll()]);
